Sample check: 40 GB -> 15*15 + 15*13 + 10*11 = 225 + 195 + 110 = Rs.530.

import java.util.Scanner;

class CloudStorage
{
    int acno;       // account number
    int space;      // storage space purchased in GB
    double bill;    // total price to be paid

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter account number: ");
        acno = sc.nextInt();
        System.out.print("Enter storage space (GB): ");
        space = sc.nextInt();
    }

    void calculate()
    {
        if (space <= 15)
            bill = space * 15;
        else if (space <= 30)
            bill = 15 * 15 + (space - 15) * 13;
        else
            bill = 15 * 15 + 15 * 13 + (space - 30) * 11;
    }

    void display()
    {
        System.out.println("Account number : " + acno);
        System.out.println("Storage space  : " + space + " GB");
        System.out.println("Bill (Rs)      : " + bill);
    }

    public static void main(String args[])
    {
        CloudStorage ob = new CloudStorage();
        ob.accept();
        ob.calculate();
        ob.display();
    }
}

Sample check: sum of squares = 201, NORM = Math.sqrt(201) = 14.177446878757825.

import java.util.Scanner;

class Norm
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int a[][] = new int[4][4];
        int sum = 0;            // sum of squares of all elements
        System.out.println("Enter 16 integers:");
        for (int i = 0; i < 4; i++)
        {
            for (int j = 0; j < 4; j++)
            {
                a[i][j] = sc.nextInt();
                sum = sum + a[i][j] * a[i][j];
            }
        }
        double norm = Math.sqrt(sum);
        System.out.println("Sum of squares of elements = " + sum);
        System.out.println("NORM = " + norm);
    }
}

Sample check: "COmmITmeNt" -> uppercase C, O, I, T, N = 5; lowercase m, m, m, e, t = 5 -> Super String.

import java.util.Scanner;

class SuperString
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String s = sc.nextLine();
        int upper = 0, lower = 0;   // counts of uppercase and lowercase letters
        for (int i = 0; i < s.length(); i++)
        {
            char ch = s.charAt(i);
            if (Character.isUpperCase(ch))
                upper++;
            else if (Character.isLowerCase(ch))
                lower++;
        }
        System.out.println("Number of Uppercase letters - " + upper);
        System.out.println("Number of Lowercase letters - " + lower);
        if (upper == lower)
            System.out.println("String is a Super String");
        else
            System.out.println("String is not a Super String");
    }
}

The array is already in ascending order of Unicode values (uppercase letters 65-90 come before 'b' = 98 and 'd' = 100), so binary search works directly. Sample check: 'S' -> mid index 5 ('U'), then high = 4, mid 2 ('N'), low = 3, mid 3 ('P'), low = 4, mid 4 ('S') -> Search Successful.

import java.util.Scanner;

class BinSearch
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        char a[] = {'A', 'H', 'N', 'P', 'S', 'U', 'W', 'Y', 'Z', 'b', 'd'};
        System.out.print("Enter the character to search: ");
        char key = sc.next().charAt(0);
        int low = 0, high = a.length - 1;
        boolean found = false;
        while (low <= high)
        {
            int mid = (low + high) / 2;
            if (a[mid] == key)
            {
                found = true;
                break;
            }
            else if (key < a[mid])
                high = mid - 1;
            else
                low = mid + 1;
        }
        if (found)
            System.out.println("Search Successful");
        else
            System.out.println("Search is not Successful");
    }
}

Sample check: print() gives 5 rows of @#@#@; print(1.0, 4.0) displays 1.0 + 1.5 + 2.0 + 2.5 + 3.0 + 3.5 + 4.0 = 17.5 and returns 17.5; print('A', 'z') returns 122.

class Overload
{
    // prints 5 rows of @#@#@ using nested loops
    void print()
    {
        for (int i = 1; i <= 5; i++)
        {
            for (int j = 1; j <= 5; j++)
            {
                if (j % 2 == 1)
                    System.out.print("@");
                else
                    System.out.print("#");
            }
            System.out.println();
        }
    }

    // displays a + (a+0.5) + ... + b and returns the sum
    double print(double a, double b)
    {
        double sum = 0.0;
        for (double x = a; x <= b; x = x + 0.5)
        {
            sum = sum + x;
            if (x + 0.5 <= b)
                System.out.print(x + " + ");
            else
                System.out.print(x);
        }
        System.out.println(" = " + sum);
        return sum;
    }

    // returns the ASCII code of the larger character
    int print(char ch1, char ch2)
    {
        if (ch1 > ch2)
            return (int) ch1;
        else
            return (int) ch2;
    }

    public static void main(String args[])
    {
        Overload ob = new Overload();
        ob.print();
        double s = ob.print(1.0, 4.0);
        System.out.println("Sum = " + s);
        System.out.println("ASCII code of larger character = " + ob.print('A', 'z'));
    }
}

Sample check: 6425 -> largest 6, smallest 2, sum 8 -> Sum is even; 3748 -> largest 8, smallest 3, sum 11 -> Sum is odd.

import java.util.Scanner;

class DigitSum
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = sc.nextInt();
        int large = 0, small = 9;   // largest and smallest digit
        int n = num;
        do
        {
            int d = n % 10;
            if (d > large)
                large = d;
            if (d < small)
                small = d;
            n = n / 10;
        } while (n > 0);
        System.out.println("Largest digit: " + large);
        System.out.println("Smallest digit: " + small);
        if ((large + small) % 2 == 0)
            System.out.println("Sum is even");
        else
            System.out.println("Sum is odd");
    }
}
